import React from 'react';
import ComicCard from '../components/ComicCard';

const comics = [
  { id: 1, title: 'The Brave Hero', genre: 'Action', image: 'https://via.placeholder.com/150' },
  { id: 2, title: 'Galaxy Tales', genre: 'Sci-Fi', image: 'https://via.placeholder.com/150' }
];

function Comics() {
  return (
    <div>
      <h2>All Comics</h2>
      <div className="comic-list">
        {comics.map(comic => (
          <ComicCard key={comic.id} comic={comic} />
        ))}
      </div>
    </div>
  );
}

export default Comics;
